# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: delulu-smash as a desktop app: the services/ui Reflex app in an
#          Omarchy web app window. `open` (SUPER+SHIFT+I) makes sure the server is up, then
#          opens or focuses the window; `serve` is what delulu-smash.service runs at login.
# Usage: delulu-smash.sh [open|serve|status]
#
# Example CLI Commands:
#   1. Open or focus the window:   .os/scripts/keybindings/delulu-smash.sh
#   2. Run the server (systemd):   .os/scripts/keybindings/delulu-smash.sh serve
#   3. Is the server up?           .os/scripts/keybindings/delulu-smash.sh status
# ---------------------------------------------------------------------------

# /// script
# requires-python = ">=3.13"
# dependencies = [
#     "typer>=0.23.0",
# ]
# ///

from __future__ import annotations

import os
import shutil
import subprocess
import time
import urllib.request
from pathlib import Path

import typer

NAME = "delulu-smash"
SERVICE = "delulu-smash.service"
REPO_DIR = Path(__file__).resolve().parents[3]
APP_DIR = REPO_DIR / "services" / "ui"
FRONTEND_URL = "http://localhost:3000"
BACKEND_PING = "http://127.0.0.1:8000/ping"
# A cold `reflex run` (frontend build + dev server) takes about a minute.
START_TIMEOUT_SECONDS = 150

app = typer.Typer(add_completion=False, no_args_is_help=False, help=__doc__)


def _up(url: str) -> bool:
    try:
        with urllib.request.urlopen(url, timeout=2) as response:  # noqa: S310  # fixed localhost URLs
            return response.status < 500
    except OSError:
        return False


def ready() -> bool:
    """Both halves of the Reflex app answer: the page and the backend it talks to."""
    return _up(FRONTEND_URL) and _up(BACKEND_PING)


def notify(message: str, *, critical: bool = False) -> None:
    if shutil.which("notify-send"):
        urgency = ["-u", "critical"] if critical else []
        subprocess.run(["notify-send", *urgency, "-a", NAME, NAME, message], check=False)


@app.callback(invoke_without_command=True)
def main(ctx: typer.Context) -> None:
    """Open delulu-smash (the default when no command is given)."""
    if ctx.invoked_subcommand is None:
        open_window()


@app.command("open")
def open_window() -> None:
    """Start the server if needed, then open the delulu-smash window or focus the open one."""
    if not ready():
        notify("Starting delulu-smash, this takes up to a minute…")
        subprocess.run(["systemctl", "--user", "start", SERVICE], check=False)
        deadline = time.monotonic() + START_TIMEOUT_SECONDS
        while not ready():
            if time.monotonic() > deadline:
                notify(f"Server didn't come up. Check: journalctl --user -u {SERVICE}", critical=True)
                raise typer.Exit(1)
            time.sleep(1)
    # Match the web app window by its class (Chromium derives it from the URL), not the
    # title: a normal browser tab on the same page is also titled "delulu-smash".
    window_class = subprocess.run(
        ["omarchy-webapp-window-class", FRONTEND_URL], capture_output=True, text=True, check=True
    ).stdout.strip()
    launcher = ["omarchy-launch-or-focus-webapp", window_class, FRONTEND_URL]
    os.execvp(launcher[0], launcher)  # noqa: S606  # fixed command, replaces this process


@app.command()
def serve() -> None:
    """Run the Reflex dev server in the foreground (what delulu-smash.service runs)."""
    os.chdir(APP_DIR)
    os.execvp("uv", ["uv", "run", "reflex", "run"])  # noqa: S606  # fixed command for systemd


@app.command()
def status() -> None:
    """Say whether the server is answering."""
    typer.echo("up" if ready() else "down")
    raise typer.Exit(0 if ready() else 1)


if __name__ == "__main__":
    app()
